#ifndef PIXAURA_INFERENCE_BOUNDARY_HPP
#define PIXAURA_INFERENCE_BOUNDARY_HPP
#include "inference_fixtures.hpp"
#include "model_package_fixtures.hpp"
#include <thread>
#include <chrono>
#include <cstdio>
namespace pixaura::inference {
inline int certification(){
    std::atomic<int> failures{0};auto expect=[&](int actual,int expected){if(actual!=expected)++failures;};
    const auto data=fixtures::cases();
    // Independent IEEE boundary vectors, including gradual underflow and ties.
    for(uint32_t bits:{0u,1u,2u,0x7fffffu,0x800000u,0x3e800000u,0x3f000000u,0x3f800000u}){
        float value=0;std::memcpy(&value,&bits,4);const auto round=binary32_round(binary32_value(value));uint32_t actual=0;std::memcpy(&actual,&round,4);if(actual!=bits)++failures;
    }
    if(binary32_round(1.0+std::ldexp(1.0,-24))!=1.0f)++failures;
    static std::atomic<uint64_t> test_id{1};
    auto init=[&](pixaura_inference_context& c,char id,uint64_t ceiling=67108864){std::array<uint8_t,32> identity{};identity.fill(static_cast<uint8_t>(id));
        auto serial=test_id.fetch_add(1);const char hex[]="0123456789abcdef";for(size_t i=0;i<16;++i){identity[31-i]=static_cast<uint8_t>(hex[serial&15]);serial>>=4;}
        expect(pixaura_inference_context_init(1,&c,sizeof(c),identity.data(),32,ceiling),0);};
    auto admit=[&](pixaura_inference_context& c,const fixtures::Case& f){
        pixaura::model::Key key{7,2,1,1,pixaura::model::fixtures::key};pixaura_model_package* raw=nullptr;pixaura_model_diagnostic diagnostic{};
        const auto status=pixaura::model::verify_owned(1,{{"manifest.pxm",f.manifest},{"signature.pxs",f.signature},{"reference.onnx",f.payload}},{1,1,2,&key,1},67108864,&raw,&diagnostic);expect(status,0);
        const auto h=live(&c);Entry e{};e.kind=1;e.package=adopt(h,std::unique_ptr<pixaura_model_package>(raw));std::lock_guard<std::mutex> lock(h.state->mutex);return insert_locked(h,std::move(e));
    };
    auto prepare=[&](pixaura_inference_context& c,const pixaura_inference_handle& p,pixaura_inference_handle& m){return pixaura_inference_prepare(&c,provider.data(),provider.size(),&p,&m,sizeof(m));};
    auto request=[&](uint32_t h,uint32_t w,uint64_t generation=1){pixaura_inference_request r{};r.version=1;r.struct_size=sizeof(r);r.task=1;r.generation=generation;
        r.input=tensor({{1,3,h,w}},{{1000000,0,1000000,0,1000000,0}});return r;};
    auto execute=[&](pixaura_inference_context& c,const pixaura_inference_handle& m,const pixaura_inference_request& r,const std::vector<float>& input,pixaura_inference_handle& out){
        return pixaura_inference_execute(&c,&m,&r,sizeof(r),reinterpret_cast<const uint8_t*>(input.data()),input.size()*4,&out,sizeof(out));};
    auto copy=[&](pixaura_inference_context& c,const pixaura_inference_handle& out,size_t count){std::vector<float> v(count);expect(pixaura_inference_output_copy(&c,&out,reinterpret_cast<uint8_t*>(v.data()),v.size()*4),0);return v;};
    pixaura_inference_descriptor d{};expect(pixaura_inference_descriptor_query(1,provider.data(),provider.size(),&d,sizeof(d)),0);
    if(std::strcmp(d.provider_id,"cpu.reference.v1")||d.task!=1||d.backend!=1||d.availability!=2||!d.deterministic)++failures;
    expect(pixaura_inference_descriptor_query(1,"unknown",7,&d,sizeof(d)),4);
    expect(pixaura_inference_descriptor_query(2,provider.data(),provider.size(),&d,sizeof(d)),2);
    for(const auto& f:data){pixaura_inference_context c{};init(c,'a');auto p=admit(c,f);pixaura_inference_handle m{};expect(prepare(c,p,m),f.status);
        if(f.status&&m.serial){++failures;}if(!f.status){expect(pixaura_inference_release(&c,&m),0);}
        expect(pixaura_inference_release(&c,&p),0);expect(pixaura_inference_context_destroy(&c),0);expect(pixaura_inference_context_destroy(&c),14);
    }
    // Independent integer/dyadic goldens, not outputs generated by the interpreter.
    pixaura_inference_context c{};init(c,'b');auto p=admit(c,data.back());pixaura_inference_handle m{};expect(prepare(c,p,m),0);
    uint64_t generation=1;
    for(const auto& g:fixtures::goldens()){auto r=request(2,2,generation++);std::vector<float> in;for(auto q:g.input_units)in.push_back(static_cast<float>(q)/4);
        const auto start=std::chrono::steady_clock::now();pixaura_inference_handle out{};expect(execute(c,m,r,in,out),0);
        const auto micros=std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-start).count();
        pixaura_inference_resources observed{};expect(pixaura_inference_resources_query(&c,&observed,sizeof(observed)),0);
        std::printf("CPU reference tiny fixture %s: pixels=4 execute_us=%lld owned_reserved=%llu input_bytes=48 output_bytes=16 scratch_bytes=0\n",g.name,static_cast<long long>(micros),static_cast<unsigned long long>(observed.reserved_bytes));
        const auto v=copy(c,out,4);for(size_t i=0;i<4;++i){uint32_t bits=0;std::memcpy(&bits,&v[i],4);if(bits!=g.output_bits[i])++failures;}
        pixaura_inference_output info{};expect(pixaura_inference_output_info(&c,&out,&info,sizeof(info)),0);if(info.generation!=r.generation||info.tensor.dimensions[1]!=1||info.tensor.bytes!=16)++failures;
        std::array<uint8_t,16> sentinel{};sentinel.fill(0x55);expect(pixaura_inference_output_copy(&c,&out,sentinel.data(),15),17);if(sentinel[0]!=0x55)++failures;
        expect(pixaura_inference_release(&c,&out),0);expect(pixaura_inference_release(&c,&out),14);
    }
    std::vector<float> in(12,.5f);auto r=request(2,2,generation++);pixaura_inference_handle out{};
    auto bad=[&](pixaura_inference_request b,int status){b.generation=generation++;out={};expect(execute(c,m,b,in,out),status);if(out.serial)++failures;};
    auto b=r;b.task=2;bad(b,7);b=r;b.input.rank=3;bad(b,8);b=r;b.input.dimensions[2]=UINT32_MAX;bad(b,8);
    b=r;b.input.type=2;bad(b,9);b=r;b.input.layout=2;bad(b,9);b=r;b.input.bytes++;bad(b,8);
    b=r;b.input.normalization[0]=2000000;bad(b,18);b=r;b.pre_cancel=1;bad(b,12);
    r.generation=generation++;out={};expect(pixaura_inference_execute(&c,&m,&r,sizeof(r),reinterpret_cast<const uint8_t*>(in.data()),47,&out,sizeof(out)),8);
    r.generation=generation++;expect(pixaura_inference_execute(&c,&m,&r,sizeof(r),nullptr,48,&out,sizeof(out)),1);
    alignas(8) std::array<uint8_t,256> aliased{};r.generation=generation++;
    expect(pixaura_inference_execute(&c,&m,&r,sizeof(r),aliased.data(),48,reinterpret_cast<pixaura_inference_handle*>(aliased.data()),sizeof(out)),1);
    for(auto x:{-0.1f,1.1f,std::numeric_limits<float>::infinity(),std::numeric_limits<float>::quiet_NaN()}){in[0]=x;r.generation=generation++;out={};expect(execute(c,m,r,in,out),10);if(out.serial)++failures;}
    in[0]=.5f;r.generation=generation++;expect(execute(c,m,r,in,out),0);expect(pixaura_inference_release(&c,&out),0);
    in.assign(12,0);const uint32_t subnormal=1;for(auto& value:in)std::memcpy(&value,&subnormal,4);
    r.generation=generation++;expect(execute(c,m,r,in,out),0);const auto tiny=copy(c,out,4);for(auto value:tiny){uint32_t bits=0;std::memcpy(&bits,&value,4);if(bits!=1)++failures;}expect(pixaura_inference_release(&c,&out),0);
    const uint32_t negative_tiny=0x80000001;std::memcpy(in.data(),&negative_tiny,4);r.generation=generation++;expect(execute(c,m,r,in,out),10);in.assign(12,.5f);
    const float invalid_output[]={0,.5f,2};if(valid_probabilities(invalid_output,3))++failures;
    live(&c).state->output_fault=true;r.generation=generation++;out={};expect(execute(c,m,r,in,out),13);if(out.serial){++failures;}live(&c).state->output_fault=false;
    expect(pixaura_inference_release(&c,&p),0);r.generation=generation++;expect(execute(c,m,r,in,out),0);expect(pixaura_inference_release(&c,&out),0);
    expect(pixaura_inference_prepare(&c,provider.data(),provider.size(),&m,&out,sizeof(out)),3);
    expect(pixaura_inference_release(&c,&m),0);r.generation=generation++;expect(execute(c,m,r,in,out),14);
    pixaura_inference_resources resources{};expect(pixaura_inference_resources_query(&c,&resources,sizeof(resources)),0);if(resources.handles||resources.reserved_bytes!=control)++failures;
    expect(pixaura_inference_context_destroy(&c),0);
    pixaura_inference_context normalized{};init(normalized,'b');auto np=admit(normalized,data[4]);pixaura_inference_handle nm{},no{};expect(prepare(normalized,np,nm),0);
    auto nr=request(8,8);nr.input.normalization[0]=500000;in.assign(192,1);expect(execute(normalized,nm,nr,in,no),0);if(copy(normalized,no,64)[0]!=.875f)++failures;
    expect(pixaura_inference_context_destroy(&normalized),0);
    // Distinguishable model weights, isolated cancellation, interleaved contexts.
    pixaura_inference_context a{},bb{};init(a,'c');init(bb,'d');const auto pa=admit(a,data[0]),pb=admit(bb,data[1]);pixaura_inference_handle ma{},mb{},oa{},ob{};
    expect(prepare(a,pa,ma),0);expect(prepare(bb,pb,mb),0);in.assign(192,0.0f);std::fill_n(in.begin(),64,1.0f);auto rr=request(8,8);
    auto cancelled=rr;cancelled.pre_cancel=1;expect(execute(a,ma,cancelled,in,oa),12);expect(execute(bb,mb,rr,in,ob),0);if(copy(bb,ob,64)[0]!=1)++failures;
    expect(execute(bb,ma,rr,in,oa),14);rr.generation=2;
    std::thread t([&]{expect(execute(a,ma,rr,in,oa),0);});expect(execute(bb,mb,rr,in,ob),0);t.join();if(copy(a,oa,64)[0]!=.25f||copy(bb,ob,64)[0]!=1)++failures;
    pixaura_inference_output identity_a{},identity_b{};expect(pixaura_inference_output_info(&a,&oa,&identity_a,sizeof(identity_a)),0);expect(pixaura_inference_output_info(&bb,&ob,&identity_b,sizeof(identity_b)),0);
    if(!std::memcmp(identity_a.manifest_sha256,identity_b.manifest_sha256,32))++failures;
    expect(pixaura_inference_context_destroy(&a),0);expect(pixaura_inference_context_destroy(&bb),0);
    // Boundary tensor, cancellation checkpoints, capacity failure, repeated cleanup.
    pixaura_inference_context large{};init(large,'e');auto lp=admit(large,data[3]);pixaura_inference_handle lm{};expect(prepare(large,lp,lm),0);
    in.assign(3*1024*1024,1);rr=request(1024,1024);expect(execute(large,lm,rr,in,oa),0);if(copy(large,oa,1024*1024).back()!=1){++failures;}expect(pixaura_inference_release(&large,&oa),0);
    struct Hook {pixaura_inference_context* c;pixaura_inference_handle* m;uint64_t generation;unsigned tiles=0;bool release=false;int status=-1,busy=-1;
        const pixaura_inference_request* request=nullptr;const std::vector<float>* input=nullptr;};
    Hook hook{&large,&lm,2};auto* state=live(&large).state;state->observer_state=&hook;
    hook.request=&rr;hook.input=&in;
    state->observer=[](evaluation::Checkpoint phase,void* opaque){auto& h=*static_cast<Hook*>(opaque);if(phase==evaluation::Checkpoint::tile){++h.tiles;
        if(h.tiles==1){auto r=*h.request;r.generation=100;pixaura_inference_handle out{};h.busy=pixaura_inference_execute(h.c,h.m,&r,sizeof(r),reinterpret_cast<const uint8_t*>(h.input->data()),h.input->size()*4,&out,sizeof(out));}
        if(h.tiles==2)h.status=h.release?pixaura_inference_release(h.c,h.m):pixaura_inference_cancel(h.c,h.m,h.generation);}};
    rr.generation=2;oa={};expect(execute(large,lm,rr,in,oa),12);expect(hook.status,0);if(oa.serial||hook.tiles!=2)++failures;
    expect(hook.busy,16);
    state->observer=nullptr;rr.generation=3;expect(execute(large,lm,rr,in,oa),0);expect(pixaura_inference_release(&large,&oa),0);
    hook.generation=4;hook.tiles=0;hook.release=true;hook.status=-1;state->observer=[](evaluation::Checkpoint phase,void* opaque){auto& h=*static_cast<Hook*>(opaque);if(phase==evaluation::Checkpoint::tile&&++h.tiles==2)h.status=pixaura_inference_release(h.c,h.m);};
    rr.generation=4;oa={};expect(execute(large,lm,rr,in,oa),12);expect(hook.status,0);if(oa.serial){++failures;}state->observer=nullptr;
    expect(pixaura_inference_context_destroy(&large),0);
    pixaura_inference_context small{};init(small,'f',control+80000);auto sp=admit(small,data[3]);pixaura_inference_handle sm{};expect(prepare(small,sp,sm),0);
    rr.generation=1;oa={};expect(execute(small,sm,rr,in,oa),11);if(oa.serial){++failures;}expect(pixaura_inference_context_destroy(&small),0);
    for(unsigned i=0;i<8;++i){pixaura_inference_context again{};init(again,'a');auto ap=admit(again,data[2]);pixaura_inference_handle am{},ao{};expect(prepare(again,ap,am),0);
        auto one=request(1,1);std::vector<float> rgb{1,0,0};expect(execute(again,am,one,rgb,ao),0);if(copy(again,ao,1)[0]!=.25f){++failures;}expect(pixaura_inference_context_destroy(&again),0);}
    pixaura_inference_context capped{};init(capped,'a');std::array<pixaura_inference_handle,32> handles{};for(auto& handle:handles)handle=admit(capped,data[0]);
    pixaura_inference_handle exhausted{};expect(prepare(capped,handles[0],exhausted),11);if(exhausted.serial)++failures;
    expect(pixaura_inference_context_destroy(&capped),0);
    // Public verifier has no caller trust injection or raw model execution shortcut.
    pixaura_inference_context untrusted{};init(untrusted,'a');pixaura_model_diagnostic diagnostic{};pixaura_inference_handle none{};
    expect(pixaura_inference_package_verify(&untrusted,"invalid",7,&none,sizeof(none),&diagnostic),3);if(none.serial)++failures;
    expect(pixaura_inference_context_destroy(&untrusted),0);return failures.load();
}
}
#endif
